20	import * as zrUtil from 'zrender/src/core/util';
21	import * as textContain from 'zrender/src/contain/text';
22	import {makeInner} from '../util/model';
23	import {
24	    makeLabelFormatter,
25	    getOptionCategoryInterval,
26	    shouldShowAllLabels
27	} from './axisHelper';
28	import Axis from './Axis';
29	import Model from '../model/Model';
30	import { AxisBaseOption } from './axisCommonTypes';
31	import OrdinalScale from '../scale/Ordinal';
32	import { AxisBaseModel } from './AxisBaseModel';
33	import type Axis2D from './cartesian/Axis2D';
34	
35	type CacheKey = string | number;
36	
37	type InnerTickLabelCache<T> = {
38	    key: CacheKey
39	    value: T
40	}[];
41	
42	interface InnerLabelCachedVal {
43	    labels: MakeLabelsResultObj[]
44	    labelCategoryInterval?: number
45	}
46	interface InnerTickCachedVal {
47	    ticks: number[]
48	    tickCategoryInterval?: number
49	}
50	
51	type InnerStore = {
52	    labels: InnerTickLabelCache<InnerLabelCachedVal>
53	    ticks: InnerTickLabelCache<InnerTickCachedVal>
54	    autoInterval: number
55	    lastAutoInterval: number
56	    lastTickCount: number
57	    axisExtent0: number
58	    axisExtent1: number
59	};
60	
61	const inner = makeInner<InnerStore, any>();
62	
63	export function createAxisLabels(axis: Axis): {
64	    labels: {
65	        level?: number,
66	        formattedLabel: string,
67	        rawLabel: string,
68	        tickValue: number
69	    }[],
70	    labelCategoryInterval?: number
71	} {
72	    // Only ordinal scale support tick interval
73	    return axis.type === 'category'
74	        ? makeCategoryLabels(axis)
75	        : makeRealNumberLabels(axis);
76	}
77	
78	/**
79	 * @param {module:echats/coord/Axis} axis
80	 * @param {module:echarts/model/Model} tickModel For example, can be axisTick, splitLine, splitArea.
81	 * @return {Object} {
82	 *     ticks: Array.<number>
83	 *     tickCategoryInterval: number
84	 * }
85	 */
86	export function createAxisTicks(axis: Axis, tickModel: AxisBaseModel): {
87	    ticks: number[],
88	    tickCategoryInterval?: number
89	} {
90	    // Only ordinal scale support tick interval
91	    return axis.type === 'category'
92	        ? makeCategoryTicks(axis, tickModel)
93	        : {ticks: zrUtil.map(axis.scale.getTicks(), tick => tick.value) };
94	}
95	
96	function makeCategoryLabels(axis: Axis) {
97	    const labelModel = axis.getLabelModel();
98	    const result = makeCategoryLabelsActually(axis, labelModel);
99	
100	    return (!labelModel.get('show') || axis.scale.isBlank())
101	        ? {labels: [], labelCategoryInterval: result.labelCategoryInterval}
102	        : result;
103	}
104	
105	function makeCategoryLabelsActually(axis: Axis, labelModel: Model<AxisBaseOption['axisLabel']>) {
106	    const labelsCache = getListCache(axis, 'labels');
107	    const optionLabelInterval = getOptionCategoryInterval(labelModel);
108	    const result = listCacheGet(labelsCache, optionLabelInterval as CacheKey);
109	
110	    if (result) {
111	        return result;
112	    }
113	
114	    let labels;
115	    let numericLabelInterval;
116	
117	    if (zrUtil.isFunction(optionLabelInterval)) {
118	        labels = makeLabelsByCustomizedCategoryInterval(axis, optionLabelInterval);
119	    }
120	    else {
121	        numericLabelInterval = optionLabelInterval === 'auto'
122	            ? makeAutoCategoryInterval(axis) : optionLabelInterval;
123	        labels = makeLabelsByNumericCategoryInterval(axis, numericLabelInterval);
124	    }
125	
126	    // Cache to avoid calling interval function repeatedly.
127	    return listCacheSet(labelsCache, optionLabelInterval as CacheKey, {
128	        labels: labels, labelCategoryInterval: numericLabelInterval
129	    });
130	}
131	
132	function makeCategoryTicks(axis: Axis, tickModel: AxisBaseModel) {
133	    const ticksCache = getListCache(axis, 'ticks');
134	    const optionTickInterval = getOptionCategoryInterval(tickModel);
135	    const result = listCacheGet(ticksCache, optionTickInterval as CacheKey);
136	
137	    if (result) {
138	        return result;
139	    }
140	
141	    let ticks: number[];
142	    let tickCategoryInterval;
143	
144	    // Optimize for the case that large category data and no label displayed,
145	    // we should not return all ticks.
146	    if (!tickModel.get('show') || axis.scale.isBlank()) {
147	        ticks = [];
148	    }
149	
150	    if (zrUtil.isFunction(optionTickInterval)) {
151	        ticks = makeLabelsByCustomizedCategoryInterval(axis, optionTickInterval, true);
152	    }
153	    // Always use label interval by default despite label show. Consider this
154	    // scenario, Use multiple grid with the xAxis sync, and only one xAxis shows
155	    // labels. `splitLine` and `axisTick` should be consistent in this case.
156	    else if (optionTickInterval === 'auto') {
157	        const labelsResult = makeCategoryLabelsActually(axis, axis.getLabelModel());
158	        tickCategoryInterval = labelsResult.labelCategoryInterval;
159	        ticks = zrUtil.map(labelsResult.labels, function (labelItem) {
160	            return labelItem.tickValue;
161	        });
162	    }
163	    else {
164	        tickCategoryInterval = optionTickInterval;
165	        ticks = makeLabelsByNumericCategoryInterval(axis, tickCategoryInterval, true);
166	    }
167	
168	    // Cache to avoid calling interval function repeatedly.
169	    return listCacheSet(ticksCache, optionTickInterval as CacheKey, {
170	        ticks: ticks, tickCategoryInterval: tickCategoryInterval
171	    });
172	}
173	
174	function makeRealNumberLabels(axis: Axis) {
175	    const ticks = axis.scale.getTicks();
176	    const labelFormatter = makeLabelFormatter(axis);
177	    return {
178	        labels: zrUtil.map(ticks, function (tick, idx) {
179	            return {
180	                level: tick.level,
181	                formattedLabel: labelFormatter(tick, idx),
182	                rawLabel: axis.scale.getLabel(tick),
183	                tickValue: tick.value
184	            };
185	        })
186	    };
187	}
188	
189	// Large category data calculation is performance sensitive, and ticks and label
190	// probably will be fetched multiple times. So we cache the result.
191	// axis is created each time during a ec process, so we do not need to clear cache.
192	function getListCache(axis: Axis, prop: 'ticks'): InnerStore['ticks'];
193	function getListCache(axis: Axis, prop: 'labels'): InnerStore['labels'];
194	function getListCache(axis: Axis, prop: 'ticks' | 'labels') {
195	    // Because key can be a function, and cache size always is small, we use array cache.
196	    return inner(axis)[prop] || (inner(axis)[prop] = []);
197	}
198	
199	function listCacheGet<T>(cache: InnerTickLabelCache<T>, key: CacheKey): T {
200	    for (let i = 0; i < cache.length; i++) {
201	        if (cache[i].key === key) {
202	            return cache[i].value;
203	        }
204	    }
205	}
206	
207	function listCacheSet<T>(cache: InnerTickLabelCache<T>, key: CacheKey, value: T): T {
208	    cache.push({key: key, value: value});
209	    return value;
210	}
211	
212	function makeAutoCategoryInterval(axis: Axis) {
213	    const result = inner(axis).autoInterval;
214	    return result != null
215	        ? result
216	        : (inner(axis).autoInterval = axis.calculateCategoryInterval());
217	}
218	
219	/**
220	 * Calculate interval for category axis ticks and labels.
221	 * To get precise result, at least one of `getRotate` and `isHorizontal`
222	 * should be implemented in axis.
223	 */
224	export function calculateCategoryInterval(axis: Axis) {
225	    const params = fetchAutoCategoryIntervalCalculationParams(axis);
226	    const labelFormatter = makeLabelFormatter(axis);
227	    const rotation = (params.axisRotate - params.labelRotate) / 180 * Math.PI;
228	
229	    const ordinalScale = axis.scale as OrdinalScale;
230	    const ordinalExtent = ordinalScale.getExtent();
231	    // Providing this method is for optimization:
232	    // avoid generating a long array by `getTicks`
233	    // in large category data case.
234	    const tickCount = ordinalScale.count();
235	
236	    if (ordinalExtent[1] - ordinalExtent[0] < 1) {
237	        return 0;
238	    }
239	
240	    let step = 1;
241	    // Simple optimization. Empirical value: tick count should less than 40.
242	    if (tickCount > 40) {
243	        step = Math.max(1, Math.floor(tickCount / 40));
244	    }
245	    let tickValue = ordinalExtent[0];
246	    const unitSpan = axis.dataToCoord(tickValue + 1) - axis.dataToCoord(tickValue);
247	    const unitW = Math.abs(unitSpan * Math.cos(rotation));
248	    const unitH = Math.abs(unitSpan * Math.sin(rotation));
249	
250	    let maxW = 0;
251	    let maxH = 0;
252	
253	    // Caution: Performance sensitive for large category data.
254	    // Consider dataZoom, we should make appropriate step to avoid O(n) loop.
255	    for (; tickValue <= ordinalExtent[1]; tickValue += step) {
256	        let width = 0;
257	        let height = 0;
258	
259	        // Not precise, do not consider align and vertical align
260	        // and each distance from axis line yet.
261	        const rect = textContain.getBoundingRect(
262	            labelFormatter({ value: tickValue }), params.font, 'center', 'top'
263	        );
264	        // Magic number
265	        width = rect.width * 1.3;
266	        height = rect.height * 1.3;
267	
268	        // Min size, void long loop.
269	        maxW = Math.max(maxW, width, 7);
270	        maxH = Math.max(maxH, height, 7);
271	    }
272	
273	    let dw = maxW / unitW;
274	    let dh = maxH / unitH;
275	    // 0/0 is NaN, 1/0 is Infinity.
276	    isNaN(dw) && (dw = Infinity);
277	    isNaN(dh) && (dh = Infinity);
278	    let interval = Math.max(0, Math.floor(Math.min(dw, dh)));
279	
280	    const cache = inner(axis.model);
281	    const axisExtent = axis.getExtent();
282	    const lastAutoInterval = cache.lastAutoInterval;
283	    const lastTickCount = cache.lastTickCount;
284	
285	    // Use cache to keep interval stable while moving zoom window,
286	    // otherwise the calculated interval might jitter when the zoom
287	    // window size is close to the interval-changing size.
288	    // For example, if all of the axis labels are `a, b, c, d, e, f, g`.
289	    // The jitter will cause that sometimes the displayed labels are
290	    // `a, d, g` (interval: 2) sometimes `a, c, e`(interval: 1).
291	    if (lastAutoInterval != null
292	        && lastTickCount != null
293	        && Math.abs(lastAutoInterval - interval) <= 1
294	        && Math.abs(lastTickCount - tickCount) <= 1
295	        // Always choose the bigger one, otherwise the critical
296	        // point is not the same when zooming in or zooming out.
297	        && lastAutoInterval > interval
298	        // If the axis change is caused by chart resize, the cache should not
299	        // be used. Otherwise some hidden labels might not be shown again.
300	        && cache.axisExtent0 === axisExtent[0]
301	        && cache.axisExtent1 === axisExtent[1]
302	    ) {
303	        interval = lastAutoInterval;
304	    }
305	    // Only update cache if cache not used, otherwise the
306	    // changing of interval is too insensitive.
307	    else {
308	        cache.lastTickCount = tickCount;
309	        cache.lastAutoInterval = interval;
310	        cache.axisExtent0 = axisExtent[0];
311	        cache.axisExtent1 = axisExtent[1];
312	    }
313	
314	    return interval;
315	}
316	
317	function fetchAutoCategoryIntervalCalculationParams(axis: Axis) {
318	    const labelModel = axis.getLabelModel();
319	    return {
320	        axisRotate: axis.getRotate
321	            ? axis.getRotate()
322	            : ((axis as Axis2D).isHorizontal && !(axis as Axis2D).isHorizontal())
323	            ? 90
324	            : 0,
325	        labelRotate: labelModel.get('rotate') || 0,
326	        font: labelModel.getFont()
327	    };
328	}
329	
330	interface MakeLabelsResultObj {
331	    formattedLabel: string
332	    rawLabel: string
333	    tickValue: number
334	}
335	
336	function makeLabelsByNumericCategoryInterval(axis: Axis, categoryInterval: number): MakeLabelsResultObj[];
337	/* eslint-disable-next-line */
338	function makeLabelsByNumericCategoryInterval(axis: Axis, categoryInterval: number, onlyTick: false): MakeLabelsResultObj[];
339	function makeLabelsByNumericCategoryInterval(axis: Axis, categoryInterval: number, onlyTick: true): number[];
340	function makeLabelsByNumericCategoryInterval(axis: Axis, categoryInterval: number, onlyTick?: boolean) {
341	    const labelFormatter = makeLabelFormatter(axis);
342	    const ordinalScale = axis.scale as OrdinalScale;
343	    const ordinalExtent = ordinalScale.getExtent();
344	    const labelModel = axis.getLabelModel();
345	    const result: (MakeLabelsResultObj | number)[] = [];
346	
347	    // TODO: axisType: ordinalTime, pick the tick from each month/day/year/...
348	
349	    const step = Math.max((categoryInterval || 0) + 1, 1);
350	    let startTick = ordinalExtent[0];
351	    const tickCount = ordinalScale.count();
352	
353	    // Calculate start tick based on zero if possible to keep label consistent
354	    // while zooming and moving while interval > 0. Otherwise the selection
355	    // of displayable ticks and symbols probably keep changing.
356	    // 3 is empirical value.
357	    if (startTick !== 0 && step > 1 && tickCount / step > 2) {
358	        startTick = Math.round(Math.ceil(startTick / step) * step);
359	    }
360	
361	    // (1) Only add min max label here but leave overlap checking
362	    // to render stage, which also ensure the returned list
363	    // suitable for splitLine and splitArea rendering.
364	    // (2) Scales except category always contain min max label so
365	    // do not need to perform this process.
366	    const showAllLabel = shouldShowAllLabels(axis);
367	    const includeMinLabel = labelModel.get('showMinLabel') || showAllLabel;
368	    const includeMaxLabel = labelModel.get('showMaxLabel') || showAllLabel;
369	
370	    if (includeMinLabel && startTick !== ordinalExtent[0]) {
371	        addItem(ordinalExtent[0]);
372	    }
373	
374	    // Optimize: avoid generating large array by `ordinalScale.getTicks()`.
375	    let tickValue = startTick;
376	    for (; tickValue <= ordinalExtent[1]; tickValue += step) {
377	        addItem(tickValue);
378	    }
379	
380	    if (includeMaxLabel && tickValue - step !== ordinalExtent[1]) {
381	        addItem(ordinalExtent[1]);
382	    }
383	
384	    function addItem(tickValue: number) {
385	        const tickObj = { value: tickValue };
386	        result.push(onlyTick
387	            ? tickValue
388	            : {
389	                formattedLabel: labelFormatter(tickObj),
390	                rawLabel: ordinalScale.getLabel(tickObj),
391	                tickValue: tickValue
392	            }
393	        );
394	    }
395	
396	    return result;
397	}
398	
399	type CategoryIntervalCb = (tickVal: number, rawLabel: string) => boolean;
400	
401	// When interval is function, the result `false` means ignore the tick.
402	// It is time consuming for large category data.
403	/* eslint-disable-next-line */
404	function makeLabelsByCustomizedCategoryInterval(axis: Axis, categoryInterval: CategoryIntervalCb): MakeLabelsResultObj[];
405	/* eslint-disable-next-line */
406	function makeLabelsByCustomizedCategoryInterval(axis: Axis, categoryInterval: CategoryIntervalCb, onlyTick: false): MakeLabelsResultObj[];
407	/* eslint-disable-next-line */
408	function makeLabelsByCustomizedCategoryInterval(axis: Axis, categoryInterval: CategoryIntervalCb, onlyTick: true): number[];
409	function makeLabelsByCustomizedCategoryInterval(axis: Axis, categoryInterval: CategoryIntervalCb, onlyTick?: boolean) {
410	    const ordinalScale = axis.scale;
411	    const labelFormatter = makeLabelFormatter(axis);
412	    const result: (MakeLabelsResultObj | number)[] = [];
413	
414	    zrUtil.each(ordinalScale.getTicks(), function (tick) {
415	        const rawLabel = ordinalScale.getLabel(tick);
416	        const tickValue = tick.value;
417	        if (categoryInterval(tick.value, rawLabel)) {
418	            result.push(
419	                onlyTick
420	                ? tickValue
421	                : {
422	                    formattedLabel: labelFormatter(tick),
423	                    rawLabel: rawLabel,
424	                    tickValue: tickValue
425	                }
426	            );
427	        }
428	    });
429	
430	    return result;
431	}

