import Axis from '@/src/coord/Axis';
import Model from '@/src/model/Model';
import IntervalScale from '@/src/scale/Interval';
import TimeScale from '@/src/scale/Time';
import { createAxisTicks, createAxisLabels } from '@/src/coord/axisTickLabelBuilder';
import { AxisBaseModel } from '@/src/coord/AxisBaseModel';
import { AxisBaseOption } from '@/src/coord/axisCommonTypes';

function makeValueAxis(axisOption: AxisBaseOption): Axis {
    const scale = new IntervalScale();
    scale.setExtent(0, 10);
    scale.calcNiceTicks();
    const axis = new Axis('x', scale, [0, 500]);
    axis.type = 'value';
    axis.model = new Model(axisOption) as unknown as AxisBaseModel;
    return axis;
}

function makeTimeAxis(axisOption: AxisBaseOption): Axis {
    const scale = new TimeScale();
    scale.setExtent(+new Date('2024-01-01'), +new Date('2024-12-31'));
    const axis = new Axis('x', scale, [0, 500]);
    axis.type = 'time';
    axis.model = new Model(axisOption) as unknown as AxisBaseModel;
    return axis;
}

describe('axis customValues', function () {

    it('axisTick.customValues renders ticks at the requested values', function () {
        const axis = makeValueAxis({
            type: 'value',
            axisTick: { customValues: [1.5, 4.25, 9] }
        } as AxisBaseOption);
        const result = createAxisTicks(axis, axis.getTickModel() as AxisBaseModel);
        expect(result.ticks).toEqual([1.5, 4.25, 9]);
    });

    it('axisLabel.customValues renders labels at the requested values', function () {
        const axis = makeValueAxis({
            type: 'value',
            axisLabel: { customValues: [1.5, 4.25, 9] }
        } as AxisBaseOption);
        const labels = createAxisLabels(axis).labels;
        expect(labels.map(label => label.tickValue)).toEqual([1.5, 4.25, 9]);
        expect(labels.map(label => label.formattedLabel)).toEqual(['1.5', '4.25', '9']);
    });

    it('axisLabel.customValues works with a formatter callback', function () {
        const axis = makeValueAxis({
            type: 'value',
            axisLabel: {
                customValues: [2, 7],
                formatter: function (value: number) {
                    return 'v=' + value;
                }
            }
        } as AxisBaseOption);
        const labels = createAxisLabels(axis).labels;
        expect(labels.map(label => label.formattedLabel)).toEqual(['v=2', 'v=7']);
    });

    it('time axis parses date strings, sorts them and duplicates first/last', function () {
        const axis = makeTimeAxis({
            type: 'time',
            axisTick: {
                // Intentionally unsorted and string typed.
                customValues: ['2024-06-15', '2024-03-10']
            }
        } as AxisBaseOption);
        const t0 = +new Date('2024-03-10');
        const t1 = +new Date('2024-06-15');
        const result = createAxisTicks(axis, axis.getTickModel() as AxisBaseModel);
        // Time axis needs duplicate first/last tick (see TimeScale.getTicks()).
        expect(result.ticks).toEqual([t0, t0, t1, t1]);
    });

    it('time axis accepts timestamps and Date objects', function () {
        const t = +new Date('2024-05-20');
        const axis = makeTimeAxis({
            type: 'time',
            axisTick: { customValues: [t, new Date('2024-08-01')] }
        } as AxisBaseOption);
        const t1 = +new Date('2024-08-01');
        const result = createAxisTicks(axis, axis.getTickModel() as AxisBaseModel);
        expect(result.ticks).toEqual([t, t, t1, t1]);
    });

    it('falls back to automatic tick generation without customValues', function () {
        const axis = makeValueAxis({ type: 'value' } as AxisBaseOption);
        const result = createAxisTicks(axis, axis.getTickModel() as AxisBaseModel);
        expect(result.ticks).toEqual(axis.scale.getTicks().map(tick => tick.value));
        const labels = createAxisLabels(axis).labels;
        expect(labels.map(label => label.tickValue))
            .toEqual(axis.scale.getTicks().map(tick => tick.value));
    });

});

